"""Final documents: generated by code from the draft and verified by code.

The writer writes the content as an internal draft (Markdown, or JSON for tables) in the task
folder, and this module generates the final file with python-docx, openpyxl, python-pptx or
reportlab. Then it verifies it: that it opens, that it is not empty and how many pages, sheets or
slides it has. With LibreOffice it converts it to PDF to count pages and extract images of the first
ones, which the reviewer looks at before giving the verdict.

Draft format:
- Word, PDF: Markdown (headings #, lists, tables with |, **bold**, *italics*).
- PowerPoint: Markdown; each slide starts with a “# ” title or is separated with “---”.
  Lines “Notes: ...” (or “Notas: ...”) go to the speaker notes.
- Excel: JSON {"sheets": [{"name", "columns", "rows"}]} or Markdown with tables (one sheet per
  table, named after the heading that precedes it).
"""

from __future__ import annotations

import json
import logging
import re
import shutil
import subprocess
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

log = logging.getLogger(__name__)

FORMATS = ("docx", "xlsx", "pptx", "pdf")
COUNT = {"docx": "pages", "pdf": "pages", "xlsx": "sheets", "pptx": "slides"}
VIEW_PAGES = 3
LIBREOFFICE_TIME = 120
# Font with all kinds of characters for PDFs (comes with macOS).
PDF_SOURCE = Path("/System/Library/Fonts/Supplemental/Arial Unicode.ttf")


# --- simple Markdown -----------------------------------------------------------------------------


@dataclass
class Block:
    """A piece of a parsed document, such as a title, paragraph, table or code."""

    kind: str  # title, paragraph, items, table, appointment, code, separator, notes
    text: str = ""
    level: int = 0
    sorted_items: bool = False
    elements: list[tuple[int, str]] = field(default_factory=list)  # (indent, text) in lists
    rows: list[list[str]] = field(default_factory=list)


RE_TITLE = re.compile(r"^(#{1,6})\s+(.*)$")
RE_LIST = re.compile(r"^(\s*)([-*+]|\d+[.)])\s+(.*)$")
# Speaker notes: “Notes:” and also “Notas:”, as they used to be written.
RE_NOTES = re.compile(r"(?:notes|notas):", re.IGNORECASE)
RE_SEPARATOR_TABLE = re.compile(r"^\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$")


def read_markdown(text: str) -> list[Block]:
    """Parses Markdown text into a list of Blocks."""
    blocks: list[Block] = []
    lines = text.replace("\r\n", "\n").split("\n")
    i = 0
    paragraph: list[str] = []

    def close_paragraph() -> None:
        if paragraph:
            blocks.append(Block("paragraph", " ".join(s.strip() for s in paragraph)))
            paragraph.clear()

    while i < len(lines):
        line = lines[i]
        clean = line.strip()
        if not clean:
            close_paragraph()
            i += 1
            continue
        if clean.startswith("```"):
            close_paragraph()
            code = []
            i += 1
            while i < len(lines) and not lines[i].strip().startswith("```"):
                code.append(lines[i])
                i += 1
            blocks.append(Block("code", "\n".join(code)))
            i += 1
            continue
        if re.fullmatch(r"-{3,}|\*{3,}|_{3,}", clean):
            close_paragraph()
            blocks.append(Block("separator"))
            i += 1
            continue
        m = RE_TITLE.match(clean)
        if m:
            close_paragraph()
            blocks.append(Block("title", m.group(2).strip(), level=len(m.group(1))))
            i += 1
            continue
        notes = RE_NOTES.match(clean)
        if notes:
            close_paragraph()
            blocks.append(Block("notes", clean[notes.end() :].strip()))
            i += 1
            continue
        if (
            clean.startswith("|")
            and i + 1 < len(lines)
            and RE_SEPARATOR_TABLE.match(lines[i + 1].strip())
        ):
            close_paragraph()
            rows = [_cells(clean)]
            i += 2
            while i < len(lines) and lines[i].strip().startswith("|"):
                rows.append(_cells(lines[i].strip()))
                i += 1
            blocks.append(Block("table", rows=rows))
            continue
        m = RE_LIST.match(line)
        if m:
            close_paragraph()
            sorted_items = m.group(2)[0].isdigit()
            elements = []
            while i < len(lines):
                m = RE_LIST.match(lines[i])
                if not m:
                    if lines[i].strip() and lines[i].startswith("  ") and elements:
                        indent, previous = elements[-1]
                        elements[-1] = (indent, f"{previous} {lines[i].strip()}")
                        i += 1
                        continue
                    break
                indent = len(m.group(1).replace("\t", "    ")) // 2
                if indent == 0 and m.group(2)[0].isdigit() != sorted_items:
                    break  # switches from bullets to numbered (or vice versa): new list
                elements.append((indent, m.group(3).strip()))
                i += 1
            blocks.append(Block("items", sorted_items=sorted_items, elements=elements))
            continue
        if clean.startswith(">"):
            close_paragraph()
            blocks.append(Block("appointment", clean.lstrip("> ").strip()))
            i += 1
            continue
        paragraph.append(clean)
        i += 1
    close_paragraph()
    return blocks


def _cells(line: str) -> list[str]:
    return [c.strip() for c in line.strip().strip("|").split("|")]


RE_IN_LINE = re.compile(
    r"(\*\*[^*]+\*\*|__[^_]+__|\*[^*]+\*|_[^_\s][^_]*_|`[^`]+`|\[[^\]]+\]\([^)]+\))"
)


def spans(text: str) -> list[tuple[str, bool, bool]]:
    """Text with inline formatting → [(text, bold, italics)]."""
    result = []
    for part in RE_IN_LINE.split(text):
        if not part:
            continue
        if part.startswith(("**", "__")) and len(part) > 4:
            result.append((part[2:-2], True, False))
        elif part.startswith("`") and len(part) > 2:
            result.append((part[1:-1], False, False))
        elif part.startswith("[") and "](" in part:
            m = re.match(r"\[([^\]]+)\]\(([^)]+)\)", part)
            result.append((f"{m.group(1)} ({m.group(2)})" if m else part, False, False))
        elif part.startswith(("*", "_")) and len(part) > 2:
            result.append((part[1:-1], False, True))
        else:
            result.append((part, False, False))
    return result


def no_format(text: str) -> str:
    return "".join(t for t, _, _ in spans(text))


# --- generation ------------------------------------------------------------------------------


def generate_docx(markdown: str, output: Path) -> None:
    """Writes Markdown text to a Word file using Calibri."""
    from docx import Document
    from docx.shared import Pt

    doc = Document()
    style = doc.styles["Normal"]
    style.font.name = "Calibri"
    style.font.size = Pt(11)

    def write_spans(paragraph: Any, text: str) -> None:
        for t, bold, italic in spans(text):
            run = paragraph.add_run(t)
            run.bold = bold or None
            run.italic = italic or None

    for b in read_markdown(markdown):
        if b.kind == "title":
            doc.add_heading(no_format(b.text), level=min(b.level, 4) if b.level > 1 else 1)
        elif b.kind == "paragraph":
            write_spans(doc.add_paragraph(), b.text)
        elif b.kind == "items":
            for indent, text in b.elements:
                name = "List Number" if b.sorted_items else "List Bullet"
                if indent:
                    name += f" {min(indent + 1, 3)}"
                try:
                    p = doc.add_paragraph(style=name)
                except KeyError:
                    p = doc.add_paragraph(style="List Number" if b.sorted_items else "List Bullet")
                write_spans(p, text)
        elif b.kind == "table" and b.rows:
            columns = max(len(f) for f in b.rows)
            table = doc.add_table(rows=0, cols=columns)
            table.style = "Light Grid Accent 1"
            for n, row in enumerate(b.rows):
                cells = table.add_row().cells
                for c, value in enumerate(row):
                    cells[c].text = ""
                    p = cells[c].paragraphs[0]
                    for t, bold, italic in spans(value):
                        run = p.add_run(t)
                        run.bold = True if n == 0 else (bold or None)
                        run.italic = italic or None
            doc.add_paragraph()
        elif b.kind == "appointment":
            p = doc.add_paragraph(style="Intense Quote")
            write_spans(p, b.text)
        elif b.kind == "code":
            p = doc.add_paragraph()
            run = p.add_run(b.text)
            run.font.name = "Menlo"
            run.font.size = Pt(9)
        elif b.kind == "notes":
            write_spans(doc.add_paragraph(), b.text)
        elif b.kind == "separator":
            doc.add_paragraph()
    doc.save(str(output))


def _widen(prs: Any, width: int) -> None:
    """The default template is 4:3: it stretches its boxes to the new width.

    All measurements are read before changing anything (placeholders in the layouts inherit
    those of the master) and all four are written, because setting only one would zero the
    others in an inherited placeholder.
    """
    factor = width / prs.slide_width
    shapes = list(prs.slide_master.shapes)
    for layout in prs.slide_layouts:
        shapes += list(layout.placeholders)
    measures = [(f, f.left, f.top, f.width, f.height) for f in shapes]
    for shape, x, y, w, h in measures:
        if None not in (x, y, w, h):
            shape.left, shape.top = round(x * factor), y
            shape.width, shape.height = round(w * factor), h
    prs.slide_width = width


def generate_pptx(markdown: str, output: Path) -> None:
    """Writes a 16:9 PowerPoint file from Markdown, splitting it into slides."""
    from pptx import Presentation
    from pptx.util import Inches, Pt

    prs = Presentation()
    _widen(prs, Inches(13.333))  # 16:9 (the height, 7.5 inches, does not change)
    slides: list[list[Block]] = [[]]
    for b in read_markdown(markdown):
        if b.kind == "separator":
            slides.append([])
        elif b.kind == "title" and b.level <= 2 and any(x.kind != "notes" for x in slides[-1]):
            slides.append([b])
        else:
            slides[-1].append(b)
    slides = [d for d in slides if d]
    for n, blocks in enumerate(slides):
        title = next((b.text for b in blocks if b.kind == "title"), "")
        body = [b for b in blocks if b.kind not in ("title", "notes")]
        notes = [b.text for b in blocks if b.kind == "notes"]
        tables = [b for b in body if b.kind == "table"]
        cover = (
            n == 0 and len(body) <= 1 and not tables and all(b.kind == "paragraph" for b in body)
        )
        slide = prs.slides.add_slide(prs.slide_layouts[0 if cover else 1])
        if slide.shapes.title is not None:
            slide.shapes.title.text = no_format(title)
        if cover:
            if body and len(slide.placeholders) > 1:
                slide.placeholders[1].text = no_format(body[0].text)
        else:
            frame = slide.placeholders[1].text_frame if len(slide.placeholders) > 1 else None
            lines: list[tuple[int, str]] = []
            for b in body:
                if b.kind == "items":
                    lines += b.elements
                elif b.kind in ("paragraph", "appointment", "code"):
                    lines.append((0, b.text))
            if frame is not None:
                size = Pt(24 if len(lines) <= 5 else 20 if len(lines) <= 8 else 16)
                for k, (indent, text) in enumerate(lines):
                    p = frame.paragraphs[0] if k == 0 else frame.add_paragraph()
                    p.level = min(indent, 4)
                    for t, bold, italic in spans(text):
                        run = p.add_run()
                        run.text = t
                        run.font.size = size
                        run.font.bold = bold or None
                        run.font.italic = italic or None
                if not lines and tables:
                    frame.text = ""
            for md_table in tables[:1]:
                rows, columns = len(md_table.rows), max(len(f) for f in md_table.rows)
                up = Inches(2.2 if lines else 1.6)
                shape = slide.shapes.add_table(
                    rows, columns, Inches(0.6), up, Inches(12.1), Inches(0.4) * rows
                )
                for r, row in enumerate(md_table.rows):
                    for c, value in enumerate(row):
                        cell = shape.table.cell(r, c)
                        cell.text = no_format(value)
                        for p in cell.text_frame.paragraphs:
                            for run in p.runs:
                                run.font.size = Pt(14)
        if notes:
            slide.notes_slide.notes_text_frame.text = "\n".join(notes)
    prs.save(str(output))


def sheets_of(draft: str) -> list[dict[str, Any]]:
    """Excel sheets from JSON or from the tables of a Markdown."""
    try:
        data = json.loads(draft)
    except ValueError:
        data = None
    if isinstance(data, dict) and isinstance(data.get("sheets"), list):
        return data["sheets"]
    if isinstance(data, list) and data and isinstance(data[0], dict):
        columns = list(data[0])
        return [
            {
                "name": "Data",
                "columns": columns,
                "rows": [[d.get(c) for c in columns] for d in data],
            }
        ]
    sheets = []
    last_title = None
    for b in read_markdown(draft):
        if b.kind == "title":
            last_title = no_format(b.text)
        elif b.kind == "table" and b.rows:
            name = last_title or f"Sheet {len(sheets) + 1}"
            rows = [[no_format(c) for c in f] for f in b.rows[1:]]
            sheets.append(
                {"name": name, "columns": [no_format(c) for c in b.rows[0]], "rows": rows}
            )
    return sheets


def _number(value: Any) -> Any:
    if isinstance(value, str):
        t = value.strip()
        if re.fullmatch(r"-?\d+", t):
            return int(t)
        if re.fullmatch(r"-?\d+\.\d+", t):
            return float(t)
        # With thousands separator (“1,234” or “1,234.5”).
        if re.fullmatch(r"-?\d{1,3}(?:,\d{3})+(?:\.\d+)?", t):
            return float(t.replace(",", "")) if "." in t else int(t.replace(",", ""))
        # Decimal comma (“1,5”), as in old drafts.
        if re.fullmatch(r"-?\d+,\d+", t):
            return float(t.replace(",", "."))
    return value


def generate_xlsx(draft: str, output: Path) -> None:
    """Writes an Excel file from the sheets in a draft; raises if it has no table."""
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Font, PatternFill
    from openpyxl.utils import get_column_letter

    sheets = sheets_of(draft)
    if not sheets:
        raise ValueError("the draft has no table for the Excel file")
    book = Workbook()
    book.remove(book.active)
    used: set[str] = set()
    for sheet in sheets:
        name = re.sub(r"[\[\]:*?/\\]", " ", str(sheet.get("name") or "Data")).strip()[:31] or "Data"
        base, n = name, 2
        while name in used:
            name = f"{base[:28]} {n}"
            n += 1
        used.add(name)
        ws = book.create_sheet(name)
        columns = [str(c) for c in sheet.get("columns") or []]
        if columns:
            ws.append(columns)
            for cell in ws[1]:
                cell.font = Font(bold=True)
                cell.fill = PatternFill("solid", fgColor="E8F0FD")
                cell.alignment = Alignment(vertical="center")
        for row in sheet.get("rows") or []:
            ws.append([_number(v) for v in row])
        for row in ws.iter_rows(min_row=2):
            for cell in row:
                if isinstance(cell.value, str) and re.match(r"https?://", cell.value):
                    cell.hyperlink = cell.value
                    cell.font = Font(color="1D4687", underline="single")
                if isinstance(cell.value, str) and len(cell.value) > 50:
                    cell.alignment = Alignment(wrap_text=True, vertical="top")
        widths = []
        for i, column in enumerate(ws.columns, start=1):
            data = [c for c in column[1 if columns else 0 :] if c.value is not None]
            long = max((len(str(c.value)) for c in data), default=8) + 2
            if columns:
                # The header is bold and has the filter button: it needs more
                # margin.
                long = max(long, len(str(column[0].value or "")) + 5)
            widths.append(min(max(10, long), 60))
            ws.column_dimensions[get_column_letter(i)].width = widths[-1]
        if columns:
            ws.freeze_panes = "A2"
            ws.auto_filter.ref = ws.dimensions
        # When printing (and in the review images), all columns fit the width of a page;
        # landscape if the table is wide.
        ws.page_setup.orientation = "landscape" if sum(widths) > 90 else "portrait"
        ws.sheet_properties.pageSetUpPr.fitToPage = True
        ws.page_setup.fitToWidth, ws.page_setup.fitToHeight = 1, 0
    book.save(str(output))


def generate_pdf(markdown: str, output: Path) -> None:
    """Writes a PDF file from Markdown text."""
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    from reportlab.platypus import (
        ListFlowable,
        ListItem,
        Paragraph,
        Preformatted,
        SimpleDocTemplate,
        Spacer,
        Table,
        TableStyle,
    )

    source = "Helvetica"
    if PDF_SOURCE.is_file():
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont

        try:
            pdfmetrics.registerFont(TTFont("ArialUnicode", str(PDF_SOURCE)))
            source = "ArialUnicode"
        except Exception:
            log.warning("could not load the font %s", PDF_SOURCE)
    styles = getSampleStyleSheet()
    for name in ("Title", "Heading1", "Heading2", "Heading3", "BodyText"):
        styles[name].fontName = source
    body = ParagraphStyle("body", parent=styles["BodyText"], fontSize=10.5, leading=14)

    def html(text: str) -> str:
        parts = []
        for t, bold, italic in spans(text):
            t = t.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            if bold:
                t = f"<b>{t}</b>"
            if italic:
                t = f"<i>{t}</i>"
            parts.append(t)
        return "".join(parts)

    history: list[Any] = []
    for b in read_markdown(markdown):
        if b.kind == "title":
            style = styles["Title"] if b.level == 1 else styles[f"Heading{min(b.level, 3)}"]
            history.append(Paragraph(html(b.text), style))
        elif b.kind in ("paragraph", "appointment", "notes"):
            history.append(Paragraph(html(b.text), body))
            history.append(Spacer(1, 4))
        elif b.kind == "items":
            items = [
                ListItem(Paragraph(html(t), body), leftIndent=12 + 12 * s) for s, t in b.elements
            ]
            history.append(ListFlowable(items, bulletType="1" if b.sorted_items else "bullet"))
            history.append(Spacer(1, 4))
        elif b.kind == "table" and b.rows:
            data = [[Paragraph(html(c), body) for c in row] for row in b.rows]
            table = Table(data, repeatRows=1)
            table.setStyle(
                TableStyle(
                    [
                        ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#C9DBF8")),
                        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8F0FD")),
                        ("VALIGN", (0, 0), (-1, -1), "TOP"),
                    ]
                )
            )
            history += [table, Spacer(1, 8)]
        elif b.kind == "code":
            history.append(Preformatted(b.text, styles["Code"]))
        elif b.kind == "separator":
            history.append(Spacer(1, 12))
    SimpleDocTemplate(
        str(output),
        pagesize=A4,
        leftMargin=2 * cm,
        rightMargin=2 * cm,
        topMargin=2 * cm,
        bottomMargin=2 * cm,
    ).build(history or [Paragraph(" ", body)])


GENERATORS = {
    "docx": generate_docx,
    "pptx": generate_pptx,
    "xlsx": generate_xlsx,
    "pdf": generate_pdf,
}


def generate(format_: str, draft: str, output: Path) -> None:
    """Writes a document in the given format, raising ValueError if unsupported."""
    if format_ not in GENERATORS:
        raise ValueError(f"format not supported: {format_}")
    output.parent.mkdir(parents=True, exist_ok=True)
    GENERATORS[format_](draft, output)


# --- verification -----------------------------------------------------------------------------


@dataclass
class Verification:
    """The result of checking a generated file: status, problems, count and views."""

    path: Path
    ok: bool = True
    problems: list[str] = field(default_factory=list)
    count: int | None = None
    unit: str = ""
    views: list[Path] = field(default_factory=list)

    def text(self) -> str:
        """Returns a one-line summary of the file name, status, count and problems."""
        parts = [f"{self.path.name}: {'OK' if self.ok else 'has problems'}"]
        if self.count is not None:
            unit = self.unit[:-1] if self.count == 1 else self.unit
            parts.append(f"{self.count} {unit}")
        if self.problems:
            parts.append("; ".join(self.problems))
        return ", ".join(parts)


def soffice() -> str | None:
    """Returns the path to LibreOffice's soffice, or None if not found."""
    return shutil.which("soffice") or next(
        (p for p in ("/Applications/LibreOffice.app/Contents/MacOS/soffice",) if Path(p).exists()),
        None,
    )


def to_pdf(path: Path, folder: Path) -> Path | None:
    """Converts an Office document to PDF with LibreOffice (headless). None if not possible."""
    binary = soffice()
    if binary is None:
        return None
    folder.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="aide-lo-") as profile:
        try:
            subprocess.run(
                [
                    binary,
                    f"-env:UserInstallation=file://{profile}",
                    "--headless",
                    "--norestore",
                    "--convert-to",
                    "pdf",
                    "--outdir",
                    str(folder),
                    str(path),
                ],
                capture_output=True,
                timeout=LIBREOFFICE_TIME,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired):
            log.warning("LibreOffice could not convert %s", path)
            return None
    pdf = folder / f"{path.stem}.pdf"
    return pdf if pdf.is_file() else None


def pdf_pages(pdf: Path) -> int:
    """Returns the number of pages in a PDF."""
    from pypdf import PdfReader

    return len(PdfReader(str(pdf)).pages)


def pdf_images(pdf: Path, destination: Path, prefix: str, pages: int = VIEW_PAGES) -> list[Path]:
    """PNG images of the first pages (pdftoppm, from poppler)."""
    binary = shutil.which("pdftoppm") or (
        "/opt/homebrew/bin/pdftoppm" if Path("/opt/homebrew/bin/pdftoppm").exists() else None
    )
    if binary is None:
        return []
    destination.mkdir(parents=True, exist_ok=True)
    for old in destination.glob(f"{prefix}-*.png"):
        old.unlink()
    try:
        subprocess.run(
            [
                binary,
                "-png",
                "-r",
                "70",
                "-f",
                "1",
                "-l",
                str(pages),
                str(pdf),
                str(destination / prefix),
            ],
            capture_output=True,
            timeout=60,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        return []
    return sorted(destination.glob(f"{prefix}-*.png"))


def verify(path: Path, expected: int | None = None, views: Path | None = None) -> Verification:
    """Checks by code that the file opens, is not empty and has a consistent count.

    If `views` is given, it leaves images of the first pages or slides there.
    """
    v = Verification(path=path)
    format_ = path.suffix.lower().lstrip(".")
    v.unit = {"pages": "pages", "sheets": "sheets", "slides": "slides"}.get(
        COUNT.get(format_, ""), ""
    )
    if not path.is_file() or path.stat().st_size == 0:
        v.ok = False
        v.problems.append("the file does not exist or is empty")
        return v
    pdf: Path | None = None
    with tempfile.TemporaryDirectory(prefix="aide-verify-") as tmp:
        try:
            if format_ == "docx":
                from docx import Document

                doc = Document(str(path))
                text = "".join(p.text for p in doc.paragraphs) + "".join(
                    c.text for t in doc.tables for f in t.rows for c in f.cells
                )
                if not text.strip():
                    v.problems.append("the document has no text")
                pdf = to_pdf(path, Path(tmp))
                v.count = pdf_pages(pdf) if pdf else None
            elif format_ == "xlsx":
                from openpyxl import load_workbook

                book = load_workbook(str(path), read_only=True)
                v.count = len(book.sheetnames)
                full = 0
                for sheet in book.worksheets:
                    if any(c is not None for row in sheet.iter_rows(values_only=True) for c in row):
                        full += 1
                book.close()
                if not full:
                    v.problems.append("no sheet has any data")
                pdf = to_pdf(path, Path(tmp)) if views else None
            elif format_ == "pptx":
                from pptx import Presentation

                prs = Presentation(str(path))
                v.count = len(prs.slides)
                with_text = sum(
                    1
                    for s in prs.slides
                    if any(
                        getattr(sh, "has_text_frame", False) and sh.text_frame.text.strip()
                        for sh in s.shapes
                    )
                )
                if not v.count:
                    v.problems.append("the presentation has no slides")
                elif not with_text:
                    v.problems.append("no slide has any text")
                pdf = to_pdf(path, Path(tmp)) if views else None
            elif format_ == "pdf":
                from pypdf import PdfReader

                reader = PdfReader(str(path))
                v.count = len(reader.pages)
                if not v.count:
                    v.problems.append("the PDF has no pages")
                pdf = path
            else:
                v.problems.append(f"format cannot be checked: {format_}")
        except Exception as e:
            v.problems.append(f"does not open ({type(e).__name__}: {str(e)[:120]})")
        if expected is not None and v.count is not None:
            margin = 1 if format_ in ("docx", "pdf") else 0
            if abs(v.count - expected) > margin:
                v.problems.append(f"it has {v.count} {v.unit} and {expected} were expected")
        if views is not None and pdf is not None and not v.problems:
            v.views = pdf_images(pdf, views, f"{path.stem}-{format_}")
    v.ok = not v.problems
    return v
